def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return: A JSON‑serialisable representation of the point or None if conversion fails.
    """
    if value is None:
        return None

    # Try to use the standard GeoJSON interface if available
    try:
        if hasattr(value, "__geo_interface__"):
            gi = value.__geo_interface__
            if isinstance(gi, dict):
                if gi.get("type") == "Point" and "coordinates" in gi:
                    # GeoJSON style coordinates are directly usable
                    return list(gi["coordinates"])
    except Exception:
        pass

    # If the point is a tuple or list of numbers, return it directly
    if isinstance(value, (tuple, list)):
        try:
            coords = list(value)
            if all(isinstance(c, (int, float, complex)) for c in coords):
                return coords
        except Exception:
            pass

    # Shapely or similar objects often expose x, y (and optionally z) properties
    try:
        if hasattr(value, "x") and hasattr(value, "y"):
            x = value.x
            y = value.y
            coords = [x, y]
            if hasattr(value, "z"):
                try:
                    z = value.z
                    coords.append(z)
                except Exception:
                    pass
            return coords
    except Exception:
        pass

    # Some objects expose a 'coords' attribute that is an iterator or sequence
    try:
        if hasattr(value, "coords"):
            # For shapely Point, coords is a sequence of (x, y)
            coords = list(value.coords)
            if coords:
                # Return the first coordinate pair
                first = coords[0]
                if isinstance(first, (tuple, list)):
                    return list(first)
    except Exception:
        pass

    # Fallback: if the object is already a dict with numeric values, return it
    try:
        if isinstance(value, dict):
            # Ensure all values are numeric
            if all(isinstance(v, (int, float, complex)) for v in value.values()):
                return value
    except Exception:
        pass

    # If none of the above worked, return None to indicate failure
    return None

def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    # Attempt to locate the underlying data structure that contains the keys.
    # We look for common attribute names that might hold the record dictionary.
    record = None
    for attr in ("_record", "data", "record", "values"):
        if hasattr(self, attr):
            record = getattr(self, attr)
            break

    # If no attribute found, attempt to use the object itself if it behaves like a mapping.
    if record is None:
        if isinstance(self, dict):
            record = self
        elif hasattr(self, "keys") and callable(getattr(self, "keys")):
            # Might be a custom mapping-like object.
            record = self
        else:
            raise AttributeError("No suitable record attribute or mapping found")

    # At this point `record` should support the dict interface.
    try:
        if isinstance(record, dict):
            return list(record.keys())
        keys_method = getattr(record, "keys", None)
        if callable(keys_method):
            # keys() may return a view; convert to list
            return list(keys_method())
        # If it's not a dictionary but iterable of (key, value) tuples:
        if hasattr(record, "__iter__"):
            keys = []
            for item in record:
                if isinstance(item, tuple) and len(item) == 2:
                    keys.append(item[0])
                else:
                    raise TypeError("Iterable items are not key-value pairs")
            return keys
    except Exception as exc:
        raise RuntimeError(f"Unable to retrieve keys from record: {exc}") from exc

    # Fallback: record is a simple object with attributes
    return [attr for attr in dir(record) if not attr.startswith("_")]

def index(self, key):
    """ Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
