    except AttributeError as e:
        raise TypeError("The object does not have a 'data' attribute to search within.") from e
    except ValueError as e:
        raise ValueError(f"Item with key {key!r} not found.") from e

def values(self, *keys):
        """
        Return the values of the record, optionally filtering to include only
        certain values by index or key.

        :param keys: indexes or keys of the items to include; if none
                     are provided, all values will be included
        :return: list of values
        :rtype: list
        """
        try:
            # Attempt to get an underlying ordered mapping
            if hasattr(self, "_data") and isinstance(self._data, dict):
                mapping = self._data
            elif isinstance(self, dict):
                mapping = self
            else:
                # Fallback: try to iterate values directly
                return list(self)
        except Exception as exc:  # pragma: no cover
            raise TypeError(f"Unable to access record values: {exc}") from exc

        all_vals = list(mapping.values())

        # If no keys specified, return all values
        if not keys:
            return all_vals

        result = []
        seen: set = set()
        for key in keys:
            # Handle integer indices (allow negatives)
            if isinstance(key, int):
                idx = key
                if idx < 0:
                    idx += len(all_vals)
                if 0 <= idx < len(all_vals):
                    item = all_vals[idx]
                    tag = ("idx", idx)
                    if tag not in seen:
                        seen.add(tag)
                        result.append(item)
                continue

            # Handle key lookups
            try:
                item = mapping[key]
                tag = ("key", key)
                if tag not in seen:
                    seen.add(tag)
                    result.append(item)
            except (KeyError, TypeError):
                # Skip invalid keys or non-mapping lookup
                continue

        return result

def discard(self, n=-1, qid=-1, dehydration_hooks=None,
                hydration_hooks=None, **handlers):
        """
        Appends a DISCARD message to the output queue.

        :param n: number of records to discard, default = -1 (ALL)
        :param qid: query ID to discard for, default = -1 (last query)
        :param dehydration_hooks:
            Hooks to dehydrate types (dict from type (class) to dehydration
            function). Dehydration functions receive the value and return an
            object of a type understood by packstream.
        :param hydration_hooks:
            Hooks to hydrate types (mapping from type (class) to
            hydration function). Hydration functions receive a value
            understood by packstream and are free to return anything.
        :param handlers: handler functions passed into the returned Response object
        """
        # Validate and normalise inputs
        try:
            if n is None:
                n = -1
            if qid is None:
                qid = -1
            n = int(n)
            qid = int(qid)
        except (TypeError, ValueError) as exc:
            raise ValueError("`n` and `qid` must be integers or None") from exc

        if n < -1:
            raise ValueError("`n` must be -1 (ALL) or a non‑negative integer")
        if qid < -1:
            raise ValueError("`qid` must be -1 (last query) or a non‑negative integer")

        # Default hooks to empty dicts when None
        dehydration_hooks = dehydration_hooks or {}
        hydration_hooks = hydration_hooks or {}

        # Construct the message payload
        payload = {
            "op": "DISCARD",
            "n": n,
            "qid": qid
        }

        # Attach any custom hooks if provided (may be useful for later processing)
        if dehydration_hooks or hydration_hooks:
            payload["hooks"] = {
                "dehydration": list(dehydration_hooks.keys()),
                "hydration": list(hydration_hooks.keys())
            }

        # Append message to the output queue
        try:
            if hasattr(self, "_output_queue") and isinstance(self._output_queue, list):
                self._output_queue.append(payload)
            else:
                raise AttributeError("Instance must have an `_output_queue` list attribute")
        except Exception as exc:
            # Wrap any unexpected queue errors
            raise RuntimeError("Failed to enqueue DISCARD message") from exc

        # Return a lightweight Response object with handlers
        # (Assumes a Response class exists in the enclosing context)
        try:
            return Response(status="queued", handlers=handlers)
        except NameError:
            # Fallback if Response is not available
            class DummyResponse:
                def __init__(self, status, handlers=None):
                    self.status = status
                    self.handlers = handlers or {}

            return DummyResponse(status="queued", handlers=handlers)

def deprecated(message):
    """
    Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass
    """
    import warnings
    from functools import wraps

    if not isinstance(message, str):
        message = str(message)

    def decorator(func):
        if not callable(func):
            raise TypeError("deprecated decorator can only be applied to callables")
        @wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(f"{func.__name__} is deprecated: {message}",
                          DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper

    return decorator

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    if not isinstance(s, str):
        raise TypeError("Input must be a string")
    numbers = []
    current = ""
    for ch in s:
        if ch.isdigit():
            current += ch
        else:
            if current:
                numbers.append(int(current))
                current = ""
    if current:
        numbers.append(int(current))
    return tuple(numbers)

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    Parameters
    ----------
    cache : Mapping
        A mapping‑like object used to store cached results.  Items are
        stored under the key returned by *key*.
    key : callable, optional
        A function that takes ``(args, kwargs)`` and returns a hashable
        key to use for caching.  Defaults to ``hashkey``.
    lock : context manager or lock object, optional
        An optional lock used to protect concurrent cache access.  The
        object must support ``__enter__`` / ``__exit__`` or ``acquire``
        / ``release`` methods.

    Returns
    -------
    decorator : callable
        A decorator that memoizes the wrapped function's result in
        *cache*.

    Notes
    -----
    If the cache raises an exception on access or write, the decorator
    falls back to computing and returning the function's result without
    storing it.  Invalid *cache* arguments are handled gracefully by
    raising a ``TypeError``.
    """
    from functools import wraps

    if cache is None:
        raise TypeError("cache argument must be a mapping-like object")

    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            # Resolve the cache key
            try:
                cache_key = key(args, kwargs)
            except Exception as exc:
                raise ValueError("cache key function raised an exception") from exc

            # Helper to read from cache
            def read_cache():
                try:
                    return cache[cache_key]
                except KeyError:
                    raise
                except Exception:
                    # If cache access fails, just propagate a KeyError
                    raise KeyError from None

            # Helper to write to cache
            def write_cache(value):
                try:
                    cache[cache_key] = value
                except Exception:
                    # Ignore write failures
                    pass

            # Acquire cache read/write under lock if provided
            if lock is not None:
                try:
                    with lock:
                        try:
                            return read_cache()
                        except KeyError:
                            pass
                except TypeError:
                    # Object does not support __enter__/__exit__; try acquire/release
                    try:
                        lock.acquire()
                        try:
                            try:
                                return read_cache()
                            except KeyError:
                                pass
                        finally:
                            lock.release()
                    except Exception:
                        # Unable to acquire lock; fall back to no lock
                        pass

                # Cache miss; compute value
                result = func(*args, **kwargs)

                # Write result under lock
                try:
                    with lock:
                        write_cache(result)
                except TypeError:
                    try:
                        lock.acquire()
                        try:
                            write_cache(result)
                        finally:
                            lock.release()
                    except Exception:
                        # Ignore lock errors
                        pass
                return result

            else:
                # No lock; just simple cache lookup
                try:
                    return read_cache()
                except KeyError:
                    pass
                except Exception:
                    # On cache access failure, compute and skip caching
                    return func(*args, **kwargs)

                # Cache miss; compute, store, and return
                result = func(*args, **kwargs)
                write_cache(result)
                return result

        return wrapper

    return decorator

