def popitem(self):
    """Remove and return the `(key, value)` pair first inserted."""
    # Attempt to use built‑in popitem that supports the `last` argument.
    try:
        return super().popitem(last=False)
    except (TypeError, AttributeError):
        # Fallback for mapping types that do not provide the `last` argument.
        pass

    try:
        first_key = next(iter(self))
    except StopIteration:
        raise KeyError("popitem(): dictionary is empty") from None

    try:
        value = self[first_key]
    except KeyError:
        # The key was removed concurrently; retry.
        return self.popitem()

    # Remove the key from the mapping.
    try:
        del self[first_key]
    except KeyError:
        # In rare race conditions this may raise; retry.
        return self.popitem()

    return first_key, value

def setdefault(self, key, default=None):
    """
    D.setdefault(k[,d]) -> D.get(k,d), also set D[k]=d if k not in D
    """
    try:
        if key in self:
            return self[key]
        self[key] = default
        return default
    except TypeError:
        raise TypeError(f"unhashable type: {type(key).__name__}") from None

def get(self, key, default=None):
    """
    D.get(k[,d]) -> D[k] if k in D, else d.  d defaults to None.
    """
    try:
        return self[key]
    except KeyError:
        return default

def cachedmethod(cache, key=hashkey, lock=None):
    """
    Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.
    """
    def decorator(func):
        def wrapper(*args, **kwargs):
            # Compute cache key using the provided key function
            try:
                cache_key = key(*args, **kwargs)
            except Exception as exc:
                raise TypeError(f"Key function raised an exception: {exc}") from exc

            # Define a simple function to get from cache
            def get_cached():
                try:
                    return cache[cache_key]
                except KeyError:
                    raise

            # Define a simple function to set cache
            def set_cached(value):
                cache[cache_key] = value

            # Attempt to retrieve from cache with optional locking
            try:
                if lock:
                    try:
                        lock.acquire()
                        try:
                            return get_cached()
                        finally:
                            lock.release()
                    except:
                        # If lock acquisition fails, proceed without lock
                        try:
                            return get_cached()
                        except KeyError:
                            pass
                else:
                    return get_cached()
            except KeyError:
                # Cache miss, compute value
                result = func(*args, **kwargs)
                # Store result back into cache
                if lock:
                    try:
                        lock.acquire()
                        try:
                            set_cached(result)
                        finally:
                            lock.release()
                    except:
                        # If lock acquisition fails, still store result without lock
                        set_cached(result)
                else:
                    set_cached(result)
                return result

        # Preserve function metadata
        wrapper.__name__ = func.__name__
        wrapper.__doc__ = func.__doc__
        wrapper.__dict__.update(func.__dict__)
        return wrapper

    return decorator

def file_to_textbuffer(file_name, encoding):
    """
    Load a file toward a text buffer (UTF-8), using the specify encoding while reading.
    CAUTION : This will read the whole file IN MEMORY.
    :param file_name: File name.
    :type file_name: str
    :param encoding: Encoding to use.
    :type encoding: str
    :return: A text buffer or None in case of error.
    :rtype str
    """
    # Validate file_name
    if isinstance(file_name, (str, bytes)):
        if not file_name:
            return None
    elif hasattr(file_name, "__fspath__"):
        try:
            # Convert to a string path
            file_name = os.fspath(file_name)
        except Exception:
            return None
    else:
        return None

    # Validate encoding
    if not isinstance(encoding, str) or not encoding:
        return None

    try:
        with open(file_name, "r", encoding=encoding) as f:
            return f.read()
    except Exception:
        return None

def _reset_logging(cls):
    """Resets logging: clears all handlers from the root logger and sets the default level."""
    import logging
    try:
        root_logger = logging.getLogger()
        # Remove all handlers
        handlers = root_logger.handlers[:]
        for handler in handlers:
            root_logger.removeHandler(handler)
            try:
                handler.close()
            except Exception:
                pass
        # Reset the level to WARNING as a safe default
        root_logger.setLevel(logging.WARNING)
        # Ensure propagation is enabled
        root_logger.propagate = True
    except Exception:
        # Silently ignore any errors during reset
        pass

def _getTargetClass(self):
    """
    Define this to return the implementation in use,
    without the 'Py' or 'Fallback' suffix.
    """
    cls_name = getattr(self, "__class__").__name__
    if not cls_name:
        raise ValueError("Unable to determine class name for target implementation.")
    # Strip known suffixes
    if cls_name.endswith("Py"):
        target = cls_name[:-2]
    elif cls_name.endswith("Fallback"):
        target = cls_name[:-len("Fallback")]
    else:
        target = cls_name
    if not target:
        raise ValueError(f"Target class name derived from '{cls_name}' is empty after stripping suffixes.")
    return target

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    # Ensure we have an iterable sequence; if not, return empty list
    try:
        seq = list(classes)
    except Exception:
        return []

    result = []
    for cls in seq:
        # Skip None entries
        if cls is None:
            continue

        # If the item is not a class, add it directly
        try:
            is_cls = isinstance(cls, type)
        except Exception:
            # In unexpected cases treat it as non-class
            result.append(cls)
            continue

        if not is_cls:
            result.append(cls)
            continue

        # Skip cls if it is a subclass of any previously kept base
        skip_add = False
        for b in result:
            try:
                if isinstance(b, type) and issubclass(cls, b):
                    skip_add = True
                    break
            except Exception:
                continue
        if skip_add:
            continue

        # Remove any existing base that is a subclass of this new class
        # (those bases become redundant because they are already included via cls)
        filtered = []
        for b in result:
            try:
                if isinstance(b, type) and issubclass(b, cls):
                    # skip removal
                    continue
                filtered.append(b)
            except Exception:
                filtered.append(b)
        result = filtered
        result.append(cls)

    return result

def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    results = []
    try:
        for name in dir(self):
            if name.startswith("_"):
                continue
            if not hasattr(self, name):
                continue
            try:
                value = getattr(self, name)
            except Exception:
                continue
            if callable(value):
                continue
            if isinstance(value, property):
                continue
            if not all and name not in self.__class__.__dict__:
                continue
            desc = ""
            try:
                desc = value.__doc__ or ""
            except Exception:
                desc = ""
            if not desc:
                try:
                    desc = getattr(value, "description", "") or ""
                except Exception:
                    desc = ""
            if not desc and hasattr(value, "field_info"):
                try:
                    field_info = getattr(value, "field_info")
                    desc = getattr(field_info, "description", "") or ""
                except Exception:
                    pass
            results.append((name, desc.strip()))
        results.sort(key=lambda x: x[0])
    except Exception:
        results = []
    return results

def _normalizeargs(sequence, output=None):
    """
    Normalize declaration arguments.

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        # Start with a new list if none provided
        output = []

    # Helper to determine if an object is a sequence that should be iterated.
    def _is_iterable(obj):
        return hasattr(obj, "__iter__") and not isinstance(obj, (str, bytes))

    # If the top-level sequence is iterable and not a string, iterate over it.
    if _is_iterable(sequence):
        for item in sequence:
            # If the item itself is a sequence (list/tuple), decide how to treat it.
            if isinstance(item, (list, tuple)) and _is_iterable(item):
                # Detect an "implements spec": all elements are non-sequences.
                if all(not _is_iterable(sub) for sub in item):
                    # Treat the whole tuple as a single implements spec.
                    output.append(item)
                else:
                    # Expand nested sequences recursively.
                    _normalizeargs(item, output)
            else:
                # Base case: not a nested sequence, add directly.
                output.append(item)
    else:
        # The input is a single (non-iterable) argument; add it.
        output.append(sequence)

    return output

def _c_optimizations_ignored():
    """
    The opposite of `_c_optimizations_required`.

    Returns:
        bool: ``True`` if C optimizations are ignored, ``False`` otherwise.
    """
    try:
        return not _c_optimizations_required()
    except Exception as exc:
        # Raise a clearer error if the required function is missing or fails
        raise RuntimeError("Unable to determine if C optimizations are required") from exc

def _c_optimizations_required():
    """
    Return a true value if the C optimizations are required.

    This uses the ``PURE_PYTHON`` variable as documented in `_use_c_impl`.
    """
    try:
        # If PURE_PYTHON is truthy, C optimizations are not required.
        return not bool(PURE_PYTHON)
    except Exception:
        # If the variable is missing or any error occurs, assume optimizations are required.
        return True

def reset(self):
        """Reset the histogram.

        Current context is reset to an empty dict.
        Bins are reinitialized with the *initial_value*
        or with *make_bins()* (depending on the initialization).
        """
        try:
            # Reset current context to an empty dict
            if hasattr(self, "context"):
                self.context = {}
            elif hasattr(self, "current_context"):
                self.current_context = {}
            # If neither attribute exists, silently ignore

            # Reinitialize bins
            if hasattr(self, "make_bins") and callable(self.make_bins):
                # Recompute bins based on the histogram's logic
                self.bins = self.make_bins()
            elif hasattr(self, "initial_value"):
                # Use the stored initial_value. Preserve length if possible
                init_val = self.initial_value
                if isinstance(init_val, (list, tuple, set)):
                    # Make a shallow copy of the initial container
                    self.bins = type(init_val)(init_val)
                else:
                    # Try to keep the original length
                    try:
                        length = len(self.bins)
                    except Exception:
                        length = None
                    if length is not None:
                        self.bins = [init_val] * length
                    else:
                        self.bins = init_val
            else:
                # No explicit method to reinitialize bins
                raise AttributeError(
                    "Histogram does not provide a way to reinitialize bins."
                )
        except Exception as exc:
            raise RuntimeError(
                f"Failed to reset histogram: {exc}"
            ) from exc

def _get_err_indices(self, coord_name):
