    if err is None:
        return []

    # Helper: flatten a nested sequence into a 1‑D list.  This is used if
    # NumPy is not available or the err object is not array‑like.
    def _flatten(seq):
        if isinstance(seq, (str, bytes)):
            return [seq]
        try:
            iter(seq)
        except TypeError:
            return [seq]
        out = []
        for sub in seq:
            out.extend(_flatten(sub))
        return out

    # Try importing NumPy for efficient handling.  Fall back to pure Python
    # list processing if NumPy is not available.
    try:
        import numpy as np  # type: ignore
        try:
            arr = np.asarray(err)
        except Exception:
            # If conversion fails, fall back to raw handling
            raise ImportError
        # Identify finite elements (i.e., valid error values).  NaN or
        # Inf are considered invalid and excluded.
        mask = np.isfinite(arr)
        # np.where returns a tuple of arrays; the first element contains the
        # indices along the first axis for a flattened view of the array.
        indices = np.where(mask)[0]
        return indices.tolist()
    except Exception:
        # Use pure Python fallback
        flat_err = _flatten(err)
        indices = []
        for idx, val in enumerate(flat_err):
            # Treat None and NaN as missing errors.
            if val is None:
                continue
            try:
                if isinstance(val, float) and val != val:  # NaN detection
                    continue
            except Exception:
                continue
            indices.append(idx)
        return indices

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    # Don't consider None or non-iterables
    if seq is None:
        return False
    try:
        # If seq is already a single element, check directly
        # Try to detect a FillRequest instance if the class is available
        try:
            if isinstance(seq, FillRequest):
                return True
        except NameError:
            # Fallback: simple duck-typing check for common attributes
            # We make a conservative guess that a FillRequest-like object
            # has at least a 'datum' and a 'source' attribute.
            if hasattr(seq, "datum") or hasattr(seq, "value"):
                return True

        # If seq is a Source sequence, we should reject it
        try:
            if is_source_seq(seq):
                return False
        except NameError:
            # If is_source_seq is not defined, we skip this check
            pass

        # Try iterating to see if any element is a FillRequest
        it = iter(seq)
    except TypeError:
        # seq is not iterable and not a single element convertible to FillRequest
        return False

    for element in it:
        try:
            if isinstance(element, FillRequest):
                return True
        except NameError:
            # Again use duck typing as a fallback
            if hasattr(element, "datum") or hasattr(element, "value"):
                return True
    return False

def is_run_el(obj):
    """Object contains executable method 'run'."""
    try:
        return callable(getattr(obj, 'run'))
    except Exception:
        return False

def is_fill_compute_el(obj):
    """Object contains executable methods 'fill' and 'compute'."""
    # Defensive handling for any invalid inputs
    if obj is None:
        return False
    try:
        # Check presence of 'fill' attribute and that it is callable
        fill_attr = getattr(obj, 'fill', None)
        if not callable(fill_attr):
            return False
        # Check presence of 'compute' attribute and that it is callable
        compute_attr = getattr(obj, 'compute', None)
        if not callable(compute_attr):
            return False
        return True
    except Exception:
        # If any unexpected error occurs, the object does not satisfy the requirement
        return False

