def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    import re
    # Regular expressions for keys and values (example patterns, adjust as needed).
    # Keys: ASCII letters, digits, underscore, hyphen, dot, 1-256 characters.
    key_pattern = re.compile(r'^[a-zA-Z0-9_.-]{1,256}$')
    # Values: same allowed characters, may be empty, 0-256 characters.
    value_pattern = re.compile(r'^[a-zA-Z0-9_.-]{0,256}$')

    errors = []

    for k, v in labels.items():
        # Validate key
        if not isinstance(k, (str, bytes)):
            errors.append({str(k): 'expected string or bytes-like object'})
        else:
            try:
                k_str = k.decode() if isinstance(k, bytes) else k
            except Exception as exc:
                errors.append({str(k): str(exc)})
                k_str = None
            if k_str is not None:
                if not key_pattern.fullmatch(k_str):
                    errors.append(
                        {k_str: f"Label key '{k_str}' does not match the regex [{key_pattern.pattern}]"}
                    )

        # Validate value
        if not isinstance(v, (str, bytes)):
            errors.append({str(v): 'expected string or bytes-like object'})
        else:
            try:
                v_str = v.decode() if isinstance(v, bytes) else v
            except Exception as exc:
                errors.append({str(v): str(exc)})
                v_str = None
            if v_str is not None:
                if not value_pattern.fullmatch(v_str):
                    errors.append(
                        {v_str: f"Label value '{v_str}' does not match the regex [{value_pattern.pattern}]"}
                    )

    if errors:
        # Assuming ValidationError is defined elsewhere and accepts a 'messages' argument
        raise ValidationError(messages=errors)

def generate_default_observer_schema(app):
    """
    Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema.

    Returns:
        dict: A mapping from resource names to the generated default observer schemas.

    Raises:
        TypeError: If ``app`` is ``None``.
        AttributeError: If required attributes are missing on ``app`` or its ``spec``.
    """
    if app is None:
        raise TypeError("app must not be None")

    spec = getattr(app, "spec", None)
    if spec is None:
        raise AttributeError("app has no 'spec' attribute")

    manifest = getattr(spec, "manifest", None)
    if manifest is None:
        raise AttributeError("spec has no 'manifest' attribute")

    # Custom observer schemas that already exist
    custom_schemas = getattr(spec, "observer_schemas", {})
    if custom_schemas is None:
        custom_schemas = {}

    default_schemas = {}

    # Handle both list and dict manifests
    if isinstance(manifest, dict):
        resources = [(name, resource) for name, resource in manifest.items() if isinstance(resource, dict)]
    elif isinstance(manifest, list):
        resources = [(None, resource) for resource in manifest if isinstance(resource, dict)]
    else:
        # If the manifest is neither list nor dict, we cannot process it
        raise TypeError("spec.manifest must be a list or dict of resource definitions")

    for idx, (key_in_manifest, res) in enumerate(resources):
        # Determine a resource name
        res_name = None
        if isinstance(res, dict):
            res_name = res.get("name") or res.get("metadata", {}).get("name")
        if not res_name:
            res_name = f"resource_{idx}"

        # Skip resources that already have a custom schema
        if res_name in custom_schemas:
            continue

        # Build a default schema that includes all top‑level keys of the resource
        schema = {}
        for k, v in res.items():
            if k == "metadata" and isinstance(v, dict):
                schema["metadata"] = {subk: True for subk in v}
            else:
                schema[k] = True

        default_schemas[res_name] = schema

    return default_schemas

def validate(self, path):
        """Validate OCFL object at path or pyfs root.

        Returns True if valid (warnings permitted), False otherwise.
        """
        # Basic sanity checks: path must be provided
        if path is None:
            return False
        try:
            # Determine if the path is a string or a file-system-like object
            if isinstance(path, str):
                # Use os.path utilities for string paths
                import os

                # Resolve to absolute path
                abs_path = os.path.abspath(path)
                if not os.path.isdir(abs_path):
                    return False
                # In a valid OCFL root there should be a ".ocfl_root" file
                root_file = os.path.join(abs_path, ".ocfl_root")
                if not os.path.isfile(root_file):
                    return False
                # The ".ocfl_root" file should contain the string "1.0" (OCFL v1.0)
                try:
                    with open(root_file, "r", encoding="utf-8") as f:
                        content = f.read().strip()
                        if content != "1.0":
                            # allow warning but still consider valid for version mismatch
                            pass
                except Exception:
                    # If we can't read the file, consider invalid
                    return False
                return True
            else:
                # Assume a pyfs-like object with typical methods
                # It should have exists() and isdir()
                if not getattr(path, "exists", None) or not getattr(path, "is_dir", None):
                    return False
                if not path.exists():
                    return False
                if not path.is_dir():
                    return False
                # Check for ".ocfl_root" file
                try:
                    root_file = path / ".ocfl_root"
                    if not root_file.exists():
                        return False
                    # Read the file content
                    with root_file.open("r", encoding="utf-8") as f:
                        content = f.read().strip()
                        if content != "1.0":
                            # Allow warning but still valid
                            pass
                except Exception:
                    return False
                return True
        except Exception:
            # Any unhandled exception results in invalid
            return False

def status_str(self, prefix=''):
        """Return string representation of validation log, with optional prefix."""
        if not isinstance(prefix, str):
            raise TypeError(f"prefix must be a string, got {type(prefix).__name__}")
        # Determine the log container.
        if hasattr(self, "log"):
            log_container = getattr(self, "log")
        elif hasattr(self, "_log"):
            log_container = getattr(self, "_log")
        else:
            raise AttributeError("The object has no 'log' or '_log' attribute for status reporting.")
        # Ensure we have an iterable of messages.
        try:
            iter(log_container)
        except TypeError:
            # Treat as a single message.
            log_container = [log_container]
        # Convert any non-string elements to string.
        messages = []
        for msg in log_container:
            if not isinstance(msg, str):
                try:
                    msg = str(msg)
                except Exception:
                    msg = "<unable to convert message to string>"
            messages.append(msg)
        # Build the prefixed string representation.
        prefixed_messages = [f"{prefix}{m}" for m in messages]
        # Join lines with newline characters.
        return "\n".join(prefixed_messages) if prefixed_messages else ""

def validate(self, inventory, extract_spec_version=False):
    """
    Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # Basic type check
    if not isinstance(inventory, dict):
        raise ValueError("inventory must be a dictionary")

    errors = []

    # Determine spec_version
    spec_version = getattr(self, "spec_version", None)

    if extract_spec_version:
        type_value = inventory.get("type")
        if type_value is None:
            errors.append("missing inventory 'type'")
        elif not isinstance(type_value, str):
            errors.append("inventory 'type' must be a string")
        else:
            # Example mapping – can be extended as needed
            type_map = {
                "alpha": "1.0",
                "beta": "2.0",
                "gamma": "3.0",
            }
            key = type_value.lower()
            if key in type_map:
                spec_version = type_map[key]
            else:
                errors.append(f"unknown inventory type '{type_value}'")
                # keep default spec_version
    # Basic validation rules
    name = inventory.get("name")
    if not name or not isinstance(name, str):
        errors.append("inventory must have a non-empty string 'name'")

    devices = inventory.get("devices")
    if not isinstance(devices, list) or not devices:
        errors.append("inventory must contain a non-empty list of 'devices'")
    else:
        for idx, dev in enumerate(devices):
            if not isinstance(dev, dict) or "id" not in dev:
                errors.append(f"device at index {idx} is invalid; must be a dict with 'id'")

    # Result
    result = {"valid": not errors, "errors": errors}
    if spec_version is not None:
        result["spec_version"] = spec_version
    return result

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Validate types
    if not isinstance(manifest_files, dict):
        raise TypeError("manifest_files must be a dict mapping file names to digest information")
    if not hasattr(digests_used, "__iter__") or isinstance(digests_used, (str, bytes)):
        raise TypeError("digests_used must be an iterable of digests (e.g., set, list, or tuple)")

    # Convert digests_used to a set for fast lookup
    digests_needed = set(digests_used)

    # Validate digests_needed are strings
    for d in digests_needed:
        if not isinstance(d, str):
            raise ValueError(f"Digest '{d}' in digests_used must be a string")

    # Build set of digests present in the manifest
    present_digests = set()
    for file_key, value in manifest_files.items():
        if isinstance(value, dict):
            digest = value.get("digest")
            if digest is None:
                raise ValueError(f"Manifest entry for file '{file_key}' missing required 'digest' key")
        else:
            digest = value
        if not isinstance(digest, str):
            raise ValueError(f"Digest for file '{file_key}' must be a string, got {type(digest).__name__}")
        present_digests.add(digest)

    # Check all needed digests are present
    missing = digests_needed - present_digests
    if missing:
        missing_str = ", ".join(sorted(missing))
        raise ValueError(f"The following required digests are missing or not used in the manifest: {missing_str}")

    # Optionally, we could warn about digests that are present but not used, but the specification
    # only requires verifying that needed digests are present and used, so we stop here.

    # If everything passes, silently succeed
    return None

def validate_as_prior_version(self, prior):
    """
    Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Basic type and None checks
    if prior is None:
        raise ValueError("The 'prior' argument cannot be None.")
    if not isinstance(prior, type(self)):
        raise TypeError("The 'prior' argument must be an instance of the same class as 'self'.")

    # Attempt to compare based on common timestamp or version attributes.
    # Order of preference: updated_at, created_at, timestamp, version.
    comparison_attrs = ["updated_at", "created_at", "timestamp", "version"]
    for attr in comparison_attrs:
        if hasattr(self, attr) and hasattr(prior, attr):
            try:
                current_val = getattr(self, attr)
                prior_val = getattr(prior, attr)
            except Exception as exc:
                raise ValueError(f"Unable to access attribute '{attr}' for comparison: {exc}")

            # Ensure values are compatible for comparison
            try:
                if prior_val >= current_val:
                    raise ValueError(
                        f"The prior inventory's {attr} ({prior_val}) must be older than "
                        f"the current inventory's {attr} ({current_val})."
                    )
                # If we get here, the comparison succeeded and prior is valid
                return
            except TypeError:
                # Comparison not supported for these types; try next attribute
                continue

    # If we exit the loop, no suitable attribute was found or comparisons failed
    raise ValueError(
        "Could not determine if 'prior' is a valid previous version of the current inventory. "
        "Please ensure that both objects expose a comparable timestamp or version attribute."
    )

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    result: dict[str, set[str]] = {}
    # inventory can be either a mapping from logical_path -> versioned data
    # or a nested mapping via a top-level "versions" key.
    for logical_path, data in inventory.items():
        # Support two common shapes: direct mapping or with a "versions" key
        if isinstance(data, dict):
            if "versions" in data:
                versions = data["versions"]
            else:
                versions = data
        else:
            continue  # skip unexpected shapes

        if not isinstance(versions, dict):
            continue

        if version not in versions:
            continue

        entry = versions[version]

        # Extract content files from the entry. They might be stored under
        # several common keys, or directly as a list/set/file path.
        content_files = None
        if isinstance(entry, dict):
            content_files = (
                entry.get("content_files")
                or entry.get("files")
                or entry.get("file_path")
                or entry.get("file")
                or entry.get("content")
            )
        if content_files is None:
            # If entry itself is list/set/path
            content_files = entry

        if content_files is None:
            continue

        # Normalise to a set of file paths
        if isinstance(content_files, (list, set, tuple)):
            result[logical_path] = set(content_files)
        else:
            result[logical_path] = {str(content_files)}
    return result

def validate_fixity(self, fixity, manifest_files):
        """Validate fixity block in inventory.

        Check the structure of the fixity block and makes sure that only files
        listed in the manifest are referenced.
        """
        # Ensure manifest_files is iterable of strings
        if not isinstance(manifest_files, (list, tuple, set)):
            raise TypeError("manifest_files must be a list, tuple, or set of file paths")
        manifest_set = set()
        for entry in manifest_files:
            if not isinstance(entry, str):
                raise TypeError(f"Each entry in manifest_files must be a string, got {type(entry)}")
            manifest_set.add(entry)

        # Validate the fixity block itself
        if not isinstance(fixity, dict):
            raise TypeError(f"Fixity must be a dict, got {type(fixity)}")

        if "files" not in fixity:
            raise ValueError("Fixity block must contain a 'files' key")

        files_list = fixity["files"]
        if not isinstance(files_list, list):
            raise TypeError(f"The 'files' entry must be a list, got {type(files_list)}")

        for idx, file_entry in enumerate(files_list):
            if not isinstance(file_entry, dict):
                raise TypeError(f"Each file entry must be a dict, got {type(file_entry)} at index {idx}")
            if "path" not in file_entry:
                raise ValueError(f"Missing 'path' in file entry at index {idx}")
            if not isinstance(file_entry["path"], str):
                raise TypeError(f"The 'path' must be a string in file entry at index {idx}")
            if file_entry["path"] not in manifest_set:
                raise ValueError(f"File referenced in fixity '{file_entry['path']}' not found in manifest")

        # If we reach this point, validation succeeded
        return True

def files_list(path):
    """
    Return the files in `path`.
    """
    import os

    # Validate input
    if not isinstance(path, (str, bytes)):
        raise TypeError(f"Expected string or bytes path, got {type(path).__name__}")

    # Check existence and that it is a directory
    if not os.path.exists(path):
        raise FileNotFoundError(f"Path does not exist: {path}")
    if not os.path.isdir(path):
        raise NotADirectoryError(f"Path is not a directory: {path}")

    try:
        entries = os.listdir(path)
    except OSError as exc:
        raise OSError(f"Could not list directory '{path}': {exc}") from exc

    files = []
    for entry in entries:
        full_path = os.path.join(path, entry)
        try:
            if os.path.isfile(full_path):
                files.append(entry)
        except OSError:
            # Skip entries that we cannot inspect
            continue

    return files

def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    result = {}
    try:
        zip_file = __import__('zipfile').ZipFile(zip_path, 'r')
    except Exception:
        return result
    try:
        # First pass: find XML files and store their content
        for name in zip_file.namelist():
            if name.lower().endswith('.xml'):
                base = __import__('os').path.splitext(__import__('os').path.basename(name))[0]
                try:
                    data = zip_file.read(name)
                except Exception:
                    data = None
                result.setdefault(base, {})['xml'] = data

        # Second pass: group other files that share the same basename
        for name in zip_file.namelist():
            if name.lower().endswith('.xml'):
                continue
            base = __import__('os').path.splitext(__import__('os').path.basename(name))[0]
            if base in result:
                try:
                    data = zip_file.read(name)
                except Exception:
                    data = None
                result[base].setdefault('files', {})[name] = data
    finally:
        try:
            zip_file.close()
        except Exception:
            pass
    return result

def files_list_from_zipfile(zip_path):
    """
    Return the files in `zip_path`

    Example:

    [
        '2318-0889-tinf-33-0421/2318-0889-tinf-33-e200069.pdf',
        '2318-0889-tinf-33-0421/2318-0889-tinf-33-e200069.xml',
        '2318-0889-tinf-33-0421/2318-0889-tinf-33-e200071.pdf',
        '2318-0889-tinf-33-0421/2318-0889-tinf-33-e200071.xml',
        '2318-0889-tinf-33-0421/2318-0889-tinf-33-e200071-gf01.tif',
        '2318-0889-tinf-33-0421/2318-0889-tinf-33-e200071-gf02.tif',
        '2318-0889-tinf-33-0421/2318-0889-tinf-33-e200071-gf03.tif',
        '2318-0889-tinf-33-0421/2318-0889-tinf-33-e200071-gf04.tif',
    ]
    """
    try:
        import os
        import zipfile
    except ImportError as exc:
        raise RuntimeError("Required modules 'os' and 'zipfile' are not available") from exc

    if not isinstance(zip_path, (str, bytes, os.PathLike)):
        raise TypeError(f"zip_path must be a path-like object, got {type(zip_path)!r}")

    path = os.fspath(zip_path)

    if not os.path.isfile(path):
        raise FileNotFoundError(f"No such file: {path}")

    try:
        with zipfile.ZipFile(path, 'r') as zf:
            # Return the internal file names exactly as stored in the zip archive.
            return zf.namelist()
    except zipfile.BadZipFile as exc:
        raise ValueError(f"The file at {path} is not a valid ZIP archive") from exc
    except PermissionError as exc:
        raise PermissionError(f"Permission denied when accessing the ZIP file at {path}") from exc
    except Exception as exc:
        raise RuntimeError(f"An unexpected error occurred while reading the ZIP file at {path}") from exc

def fix_namespace_prefix_w(content):
    """
    Convert os textos cujo padrão é `w:st="` em `w-st="`
    """
    if not isinstance(content, str):
        raise TypeError("content must be a string")
    # Replace all occurrences of the namespace prefix pattern `w:st="` with `w-st="`.
    return content.replace('w:st="', 'w-st="')

def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths.
    Return the text content of the first matched element or None if no match is found.
    """
    if node is None or not isinstance(pubdate_xpaths, (list, tuple)):
        return None
    for xpath in pubdate_xpaths:
        try:
            result = node.xpath(xpath)
            if result:
                first_match = result[0]
                # If the matched item is a string (e.g., result of string() function)
                if isinstance(first_match, str):
                    return first_match.strip()
                # If it's an element node
                if hasattr(first_match, 'text') and first_match.text is not None:
                    return first_match.text.strip()
                # Fallback: try to convert to string
                try:
                    return str(first_match).strip()
                except Exception:
                    pass
        except Exception:
            # Any XPath or execution error; skip to next
            continue
    return None

def _extract_number_and_supplment_from_issue_element(issue):
    """
    Extrai do conteúdo de <issue>xxxx</issue>, os valores number e suppl.
    Valores possíveis
    5 (suppl), 5 Suppl, 5 Suppl 1, 5 spe, 5 suppl, 5 suppl 1, 5 suppl. 1,
    25 Suppl 1, 2-5 suppl 1, 2spe, Spe, Supl. 1, Suppl, Suppl 12,
    s2, spe, spe 1, spe pr, spe2, spe.2, spepr, supp 1, supp5 1, suppl,
    suppl 1, suppl 5 pr, suppl 12, suppl 1-2, suppl. 1
    """
    import re
    try:
        # Se a entrada for um objeto XML/Element, extrair seu texto.
        if hasattr(issue, 'text'):
            content = str(issue.text)
        else:
            content = str(issue)

        content = content.strip()
        if not content:
            return (None, None)

        # Normaliza espaços
        content = re.sub(r'\s+', ' ', content)

        # Busca todos os números inteiros na string
        numbers = [int(num) for num in re.findall(r'\d+', content)]

        number = numbers[0] if numbers else None
        suppl = numbers[1] if len(numbers) >= 2 else None

        return (number, suppl)
    except Exception:
        # Em caso de erro inesperado, devolve valores None
        return (None, None)

def tzname_in_python2(namefunc):
    """
    Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    # Detect the unicode type in a way that works on both Python 2 and 3
    try:
        _unicode_type = unicode
    except NameError:
        _unicode_type = str  # In Python 3, unicode is just str

    def wrapper(*args, **kwargs):
        # Call the original name function
        name = namefunc(*args, **kwargs)

        # If the result is already a bytestring, return it unchanged.
        # In Python 2 bytes is an alias for str, so this works for both versions.
        if isinstance(name, bytes):
            return name

        # If the result is a unicode string (in either Python 2 or 3), convert it
        # to a bytestring using UTF-8 encoding, falling back to str() if necessary.
        if isinstance(name, _unicode_type):
            try:
                return name.encode('utf-8')
            except Exception:
                # Fall back to converting using the default str() conversion
                return str(name)

        # For all other types (e.g., None or already bytes in Py2), return as is.
        return name

    return wrapper

def get_versions():
    """Get version information or return default if unable to do so."""
    # Attempt to obtain the distribution's version using importlib.metadata or pkg_resources.
    try:
        # Python 3.8 and newer
        import importlib.metadata as _metadata
    except Exception:
        try:
            # Backport for older versions
            import importlib_metadata as _metadata
        except Exception:
            _metadata = None

    version = None
    if _metadata is not None:
        try:
            # Use the module name as a proxy for the distribution name.
            # In many cases __package__ or __name__ will match the distribution name.
            dist_name = __package__ or __name__
            if dist_name:
                version = _metadata.version(dist_name)
        except Exception:
            # If the distribution metadata cannot be retrieved, keep version None.
            pass

    # If we were unable to get a version, use a sensible default.
    if not version:
        return {
            'version': '0+unknown',
            'full-revisionid': None,
            'dirty': False,
            'error': 'Unable to fetch version information'
        }

    # Return the version information in a dictionary format.
    return {
        'version': version,
        'full-revisionid': None,
        'dirty': False
    }

