def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    # If pieces is None or empty, we consider that there's no '+' present
    if pieces is None:
        return '+'
    try:
        for piece in pieces:
            # Convert each piece to string and check for the presence of '+'
            if '+' in str(piece):
                return '.'
    except TypeError:
        # If pieces is not iterable, treat it as having no '+' present
        return '+'
    # If no '+' found, return '+'
    return '+'

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess
    import sys

    # Build the command list
    if isinstance(commands, (list, tuple)):
        cmd = list(commands)
    elif isinstance(commands, str):
        cmd = [commands]
    else:
        raise TypeError("commands must be a string or list/tuple of strings")

    if args:
        if isinstance(args, (list, tuple)):
            cmd.extend(args)
        else:
            raise TypeError("args must be a list or tuple of strings")

    # Determine how to capture standard error
    stderr_capture = subprocess.STDOUT if hide_stderr else subprocess.PIPE

    try:
        process = subprocess.Popen(
            cmd,
            cwd=cwd,
            stdout=subprocess.PIPE,
            stderr=stderr_capture,
            env=env,
            universal_newlines=True,
        )
        stdout, stderr_data = process.communicate()
        returncode = process.returncode

        if verbose:
            if returncode == 0:
                sys.stdout.write(stdout)
            else:
                # When hide_stderr is True, stderr_data contains combined output
                sys.stderr.write(stderr_data)

        # If hiding stderr, we set stderr to None to avoid confusion
        stderr_result = None if hide_stderr else stderr_data
        return returncode, stdout, stderr_result

    except FileNotFoundError as fnf_err:
        raise FileNotFoundError(f"Command not found: {commands}") from fnf_err
    except Exception as exc:
        raise RuntimeError(f"Error executing command '{commands}': {exc}") from exc

def register_vcs_handler(vcs, method=None):
    """Create decorator to mark a method as the handler of a VCS.

    The decorator can be used in two ways::

        @register_vcs_handler('git')
        def git_handler(...):
            ...

    or directly::

        def git_handler(...):
            ...
        register_vcs_handler('git', git_handler)

    The function is stored in a registry attached to the decorator
    function itself, accessible via ``register_vcs_handler._registry``.
    """
    # Allow the decorator to be called with or without the handler
    if method is None:
        # Return a new decorator that expects the handler
        return lambda f: register_vcs_handler(vcs, f)

    # Validate inputs
    if not isinstance(vcs, str):
        raise TypeError(f"VCS name must be a string, got {type(vcs).__name__}")
    if not callable(method):
        raise TypeError(f"Handler must be callable, got {type(method).__name__}")

    # Create registry attribute if it does not exist
    if not hasattr(register_vcs_handler, "_registry"):
        register_vcs_handler._registry = {}

    # Store the handler in the registry
    register_vcs_handler._registry[vcs] = method

    return method

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
        """
        Validate storage root hierarchy.

        Returns:
            tuple(int, int): (num_objects, good_objects)
                num_objects - number of objects checked
                good_objects - number of objects checked that were found to be valid
        """
        # Defensive: determine root path
        root = getattr(self, 'root_path', None)
        if root is None:
            # If no root, nothing to validate
            return 0, 0

        # Ensure root is a pathlib.Path or convertible
        try:
            from pathlib import Path
            root_path = Path(root)
        except Exception:
            # invalid root, return zeros
            return 0, 0

        if not root_path.exists() or not root_path.is_dir():
            # invalid directory
            return 0, 0

        num_objects = 0
        good_objects = 0

        # Iterate over entries in the root directory recursively
        for entry in root_path.rglob('*'):
            if not entry.is_file() and not entry.is_dir():
                continue  # skip special files
            num_objects += 1

            is_valid = True

            # Validate objects: attempt to open/read if file
            if validate_objects:
                if entry.is_file():
                    try:
                        with entry.open('rb') as f:
                            f.read(1)  # just attempt a read
                    except Exception as exc:
                        is_valid = False
                        if show_warnings:
                            try:
                                print(f"WARNING: Failed to read '{entry}': {exc}")
                            except Exception:
                                pass  # silence any print errors

            # Check digests: compute SHA256 and compare to a stored digest if exists
            if is_valid and check_digests:
                if entry.is_file():
                    try:
                        import hashlib
                        sha = hashlib.sha256()
                        with entry.open('rb') as f:
                            for chunk in iter(lambda: f.read(8192), b''):
                                sha.update(chunk)
                        digest = sha.hexdigest()
                        # Assume there might be a .digest file alongside
                        digest_file = entry.with_suffix(entry.suffix + '.digest')
                        if digest_file.exists():
                            try:
                                stored = digest_file.read_text().strip()
                                if stored.lower() != digest.lower():
                                    is_valid = False
                                    if show_warnings:
                                        try:
                                            print(f"WARNING: Digest mismatch for '{entry}'. Expected {stored}, got {digest}")
                                        except Exception:
                                            pass
                            except Exception as exc:
                                is_valid = False
                                if show_warnings:
                                    try:
                                        print(f"WARNING: Could not read digest file '{digest_file}': {exc}")
                                    except Exception:
                                        pass
                    except Exception as exc:
                        is_valid = False
                        if show_warnings:
                            try:
                                print(f"WARNING: Could not compute digest for '{entry}': {exc}")
                            except Exception:
                                pass

            if is_valid:
                good_objects += 1

        return num_objects, good_objects

def amend_bzparams(self, params, bug_ids):
        """Amend the Bugzilla params"""
        # Basic type validation
        if not isinstance(params, dict):
            raise ValueError("`params` must be a dictionary.")

        # Normalise bug_ids into a set of clean string ids
        if bug_ids is None:
            bug_id_set = set()
        elif isinstance(bug_ids, (list, tuple, set)):
            bug_id_set = set(bug_ids)
        elif isinstance(bug_ids, (int, str)):
            bug_id_set = {bug_ids}
        else:
            raise ValueError("`bug_ids` must be a list, tuple, set, int, or str.")

        # Clean the ids: strip whitespace and ignore empty strings
        cleaned_ids = {str(b).strip() for b in bug_id_set if b is not None and str(b).strip() != ""}
        if not cleaned_ids:
            # Nothing to do; return original params
            return params

        # Merge with any existing 'ids' key that might be present
        existing_ids = set()
        if "ids" in params:
            existing = params["ids"]
            if isinstance(existing, str):
                existing_ids = {s.strip() for s in existing.split(",") if s.strip()}
            elif isinstance(existing, (list, tuple, set)):
                existing_ids = {str(b).strip() for b in existing if b is not None and str(b).strip()}
            # Any other type is ignored

        merged_ids = existing_ids.union(cleaned_ids)

        # Store back as a comma-separated string sorted numerically when possible
        def sort_key(x):
            return int(x) if x.isdigit() else x

        params["ids"] = ",".join(sorted(merged_ids, key=sort_key))
        return params

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.
    '''
    try:
        from collections import OrderedDict
    except Exception:
        # Fallback if collections missing
        OrderedDict = dict

    # Helper function to merge two MappingNodes
    def _merge_mapping_nodes(old_map, new_map):
        # old_map.value & new_map.value are lists of (key_node, val_node) tuples
        # We use an OrderedDict to preserve insertion order
        merged_dict = OrderedDict()
        tag = getattr(old_map, 'tag', None)

        # Populate with old mapping entries
        for k_node, v_node in getattr(old_map, 'value', []):
            key = getattr(k_node, 'value', None)
            merged_dict[key] = (k_node, v_node)

        # Merge / overwrite with new mapping entries
        for k_node, v_node in getattr(new_map, 'value', []):
            key = getattr(k_node, 'value', None)
            if key in merged_dict:
                _, existing_v_node = merged_dict[key]
                # If both are MappingNodes, merge recursively
                try:
                    if isinstance(v_node, ruamel.yaml.nodes.MappingNode) and isinstance(existing_v_node, ruamel.yaml.nodes.MappingNode):
                        merged_child = _merge_mapping_nodes(existing_v_node, v_node)
                        merged_dict[key] = (merged_dict[key][0], merged_child)
                        continue
                except Exception:
                    pass
                # Otherwise, replace with the new node (last wins)
                merged_dict[key] = (merged_dict[key][0], v_node)
            else:
                merged_dict[key] = (k_node, v_node)

        # Build the list of merged (key_node, value_node) tuples
        merged_value = list(merged_dict.values())
        # Reconstruct a new MappingNode, using the type of old_map for compatibility
        try:
            merged_map = type(old_map)(tag=tag, value=merged_value)
        except Exception:
            # Fallback: create a generic MappingNode if constructor differs
            merged_map = getattr(ruamel.yaml.nodes, 'MappingNode')(tag=tag, value=merged_value)
        return merged_map

    if not isinstance(nodes, list):
        raise TypeError('nodes must be a list of (ScalarNode, Node) tuples')

    result = OrderedDict()
    for entry in nodes:
        if not isinstance(entry, tuple) or len(entry) != 2:
            continue  # skip malformed entries
        key_node, val_node = entry
        key = getattr(key_node, 'value', None)
        if key is None:
            continue  # skip if key cannot be determined

        if key not in result:
            result[key] = (key_node, val_node)
        else:
            existing_key_node, existing_val_node = result[key]
            # If both values are MappingNodes, perform deep merge
            try:
                if isinstance(val_node, ruamel.yaml.nodes.MappingNode) and isinstance(existing_val_node, ruamel.yaml.nodes.MappingNode):
                    merged_val = _merge_mapping_nodes(existing_val_node, val_node)
                    result[key] = (existing_key_node, merged_val)
                else:
                    # Replace with the new value (last wins)
                    result[key] = (existing_key_node, val_node)
            except Exception:
                # On any error, fall back to using the newer node
                result[key] = (existing_key_node, val_node)

    return list(result.values())

def parse_arguments(*arguments):
    """
    Given command-line arguments with which this script was invoked, parse the arguments
    and return them as an argparse.Namespace instance.
    """
    import argparse
    parser = argparse.ArgumentParser(description="Command-line arguments parser")
    try:
        return parser.parse_args(arguments)
    except SystemExit as exc:
        # argparse calls sys.exit() which raises SystemExit. Convert to ValueError for callers.
        raise ValueError("Argument parsing failed") from exc

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    if parser is None:
        raise TypeError("parser must not be None")
    try:
        actions = parser._actions
    except AttributeError as exc:
        raise TypeError("parser must be an argparse.ArgumentParser instance") from exc

    flags = []
    for action in actions:
        # Each action has an 'option_strings' attribute containing the flags (e.g., ['-h', '--help'])
        option_strings = getattr(action, 'option_strings', [])
        if option_strings:
            flags.extend(option_strings)

    # Remove duplicates while preserving order
    seen = set()
    unique_flags = []
    for flag in flags:
        if flag not in seen:
            seen.add(flag)
            unique_flags.append(flag)

    return ' '.join(unique_flags)

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    # Validate input
    if parser is None:
        raise ValueError("parser argument cannot be None")
    # argparse parsers expose their actions via the `_actions` attribute, but older versions
    # might expose `actions`. Use whichever is available.
    actions_attr = None
    if hasattr(parser, '_actions'):
        actions_attr = parser._actions
    elif hasattr(parser, 'actions'):
        actions_attr = parser.actions
    else:
        raise TypeError("The provided object does not appear to be an argparse.ArgumentParser")
    # Ensure the attribute is iterable
    try:
        actions_iter = iter(actions_attr)
    except Exception as exc:
        raise TypeError("Unable to iterate over parser actions") from exc
    flags = []
    for action in actions_iter:
        # Each action has an `option_strings` list of flag representations.
        # Some actions may not have option_strings (e.g., positional arguments).
        try:
            option_strings = getattr(action, 'option_strings', [])
        except Exception:
            continue
        for opt in option_strings:
            if isinstance(opt, str) and opt.startswith('-'):
                flags.append(opt)
    # Return flags as a single space-separated string
    return ' '.join(flags) if flags else ''

