    top_parser = make_parser()
    # `subparser_name` captures the first positional token if it doesn't start with '-' and isn't '--'
    top_parser.add_argument('subparser_name', nargs='?', default=None)
    try:
        top_parsed, remaining = top_parser.parse_known_args(unparsed_arguments)
    except Exception:
        # If parsing fails for unexpected reasons, return empty mapping
        return {"global": argparse.Namespace()}

    result = {}
    # Prepare the global namespace; keep the parsed top-level arguments
    result["global"] = top_parsed

    # If a subcommand has been detected, parse its arguments separately
    sub_name = top_parsed.subparser_name
    if sub_name:
        # All arguments after the subcommand name are treated as belonging to that subparser
        sub_parser = make_parser()
        try:
            sub_parsed, sub_remaining = sub_parser.parse_known_args(remaining)
        except Exception:
            # If subparser parsing fails, still return the best effort

def make_parsers():
    '''
    Build a top-level parser and its subparsers and return them as a tuple.
    '''
    try:
        parser = argparse.ArgumentParser()
        subparsers = parser.add_subparsers(dest='command')
    except NameError as exc:
        raise RuntimeError("argparse module not available.") from exc
    except Exception as exc:
        raise RuntimeError(f"Failed to create parsers: {exc}") from exc
    return parser, subparsers

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    if not hasattr(dicts, "__iter__") or isinstance(dicts, (str, bytes)):
        raise TypeError("dicts must be an iterable of dictionaries")
    result = {}
    for d in dicts:
        if not isinstance(d, dict):
            raise TypeError("elements of dicts must be dictionaries")
        for key, value in d.items():
            # Attempt to sum values; if addition fails, raise a descriptive error.
            try:
                result[key] = result.get(key, 0) + value
            except TypeError:
                raise TypeError(
                    f"cannot sum values for key '{key}': incompatible types"
                )
    return result

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    # Basic validation
    if url is None:
        return None
    if not url_args:
        return url

    # Replace placeholders of the form {key} or :key
    for key, value in url_args.items():
        # Skip keys with None values
        if value is None:
            continue
        placeholder_braces = f"{{{key}}}"
        placeholder_colon = f":{key}"
        # Replace both forms if present
        if placeholder_braces in url:
            url = url.replace(placeholder_braces, str(value))
        if placeholder_colon in url:
            url = url.replace(placeholder_colon, str(value))

    return url

def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a
    space-separated string.
    """
    # Validate input
    if not hasattr(parser, "_actions"):
        raise TypeError("parser must be an argparse.ArgumentParser instance")
    try:
        flags = []
        seen = set()
        for action in parser._actions:
            # action.option_strings is a list of option strings for an optional argument
            option_strings = getattr(action, "option_strings", None)
            if option_strings:
                for opt in option_strings:
                    if opt not in seen:
                        flags.append(opt)
                        seen.add(opt)
        return " ".join(flags)
    except Exception as exc:
        # In case of unexpected errors, re-raise with a clear message
        raise RuntimeError(f"Failed to extract flags from parser: {exc}") from exc

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    # Validate alphabet
    if not isinstance(alphabet, list) or not alphabet:
        raise ValueError("Alphabet must be a non-empty list of single-character strings.")
    for ch in alphabet:
        if not isinstance(ch, str) or len(ch) != 1:
            raise ValueError("Alphabet elements must be single-character strings.")
    base = len(alphabet)

    # Validate padding
    if padding is not None:
        if not isinstance(padding, int) or padding < 0:
            raise ValueError("Padding must be a non-negative integer or None.")

    # Handle zero case
    if number == 0:
        digits = [alphabet[0]]
    else:
        sign = '-' if number < 0 else ''
        num = abs(number)
        if base == 1:
            # Unary representation: repeat the single alphabet character
            if num == 0:
                digits = [alphabet[0]]
            else:
                digits = [alphabet[0]] * num
        else:
            digits_rev = []
            while num > 0:
                rem = num % base
                digits_rev.append(alphabet[rem])
                num //= base
            digits = list(reversed(digits_rev))

    # Apply padding if specified
    if padding is not None:
        pad_needed = padding - len(digits)
        if pad_needed > 0:
            digits = [alphabet[0]] * pad_needed + digits

    result = ''.join(digits)
    # Prepend sign if negative
    if isinstance(number, int) and number < 0:
        result = '-' + result
    return result

def _replace_register(flow_params, register_number, register_value):
    """Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number

    """
    # Basic input validation
    if flow_params is None:
        return None
    if not isinstance(register_value, str):
        raise TypeError("register_value must be a string key")
    # Helper to recursively replace key
    def _replace_in_obj(obj):
        if isinstance(obj, dict):
            new_obj = {}
            for k, v in obj.items():
                new_key = register_number if k == register_value else k
                new_obj[new_key] = _replace_in_obj(v)
            return new_obj
        elif isinstance(obj, list):
            return [_replace_in_obj(item) for item in obj]
        else:
            return obj

    return _replace_in_obj(flow_params)

def replace_dots(value, arg):
    """Replaces all values of '.' to arg from the given string"""
    if not isinstance(value, str):
        raise TypeError("value must be a string")
    if not isinstance(arg, str):
        raise TypeError("arg must be a string")
    try:
        return value.replace(".", arg)
