        raise RuntimeError("An error occurred while replacing dots") from e

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    if not isinstance(cls, type):
        raise TypeError(f"Expected a class (type), got {type(cls).__name__}")
    result = set()
    try:
        direct_subs = cls.__subclasses__()
    except Exception:
        return result
    for sub in direct_subs:
        result.add(sub)
        result.update(subclasses(sub))
    return result

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    # Basic type checks
    if not isinstance(string, str):
        raise TypeError(f"Expected string for 'string', got {type(string).__name__}")
    if not isinstance(alphabet, list):
        raise TypeError(f"Expected list for 'alphabet', got {type(alphabet).__name__}")

    # Alphabet must not be empty
    if len(alphabet) == 0:
        raise ValueError("Alphabet must contain at least one symbol")

    # Build a mapping from symbol to its numeric value, ensuring uniqueness
    mapping: Dict[str, int] = {}
    for idx, sym in enumerate(alphabet):
        if not isinstance(sym, str):
            raise TypeError(f"Alphabet elements must be strings, got {type(sym).__name__}")
        if sym in mapping:
            raise ValueError(f"Duplicate symbol '{sym}' found in alphabet")
        mapping[sym] = idx

    base = len(alphabet)

    # Empty string cannot be converted
    if string == "":
        raise ValueError("Cannot convert an empty string to an integer")

    # Convert the string to an integer using the alphabet mapping
    value = 0
    for ch in string:
        if ch not in mapping:
            raise ValueError(f"Character '{ch}' not found in the provided alphabet")
        value = value * base + mapping[ch]

    return value

def unquote(name):
    """Remove quote from the given name."""
    # Return immediately if not a string; no alteration needed.
    if not isinstance(name, str):
        return name
    # Only attempt to strip if both ends are the same quote character.
    if len(name) >= 2 and name[0] == name[-1] and name[0] in ("'", '"'):
        return name[1:-1]
    return name

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    # Handle invalid or missing input
    if not isinstance(host, str) or not host:
        return False

    # Direct name match
    if host.strip().lower() == "localhost":
        return True

    try:
        # Resolve the host to an IP address or list of addresses
        addr_infos = socket.getaddrinfo(host, None)
        for info in addr_infos:
            # the IP address is at index 4 of the tuple
            ip_addr = info[4][0]
            # IPv4 loopback
            if ip_addr == "127.0.0.1" or ip_addr.startswith("127."):
                return True
            # IPv6 loopback
            if ip_addr == "::1":
                return True
            # IPv4-mapped IPv6 loopback (::ffff:127.X.Y.Z)
            if ip_addr.startswith("::ffff:127.") or ip_addr.startswith("::ffff:"):
                # confirm it's mapped to a 127.* address
                try:
                    mapped = ip_addr.split(":")[-1]
                    if mapped.startswith("127."):
                        return True
                except Exception:
                    pass
    except socket.gaierror:
        # Hostname could not be resolved
        return False
    except Exception:
        # Any other error should not crash; consider non-local
        return False

    return False

def oneline(script, seperator=" && "):
    """
    converts a script to one line command.
    This is useful to run a single SSH command and pass a one line script.

    :param script: the script as a string or a list of lines
    :param seperator: the separator to use between commands
    :return: a single line string of the script
    """
    try:
        if script is None:
            raise ValueError("script cannot be None")
        # Accept a list of strings as well as a single string
        if isinstance(script, list):
            lines = script
        else:
            lines = str(script).splitlines()
        # Strip whitespace and filter out empty lines
        cleaned = [line.strip() for line in lines if line.strip()]
        # Join with the specified separator
        return seperator.join(cleaned)
    except Exception as exc:
        raise RuntimeError(f"Error converting script to one line: {exc}") from exc

def _resolve_string(matcher):
    """
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    if not isinstance(matcher, (tuple, list)):
        raise TypeError("matcher must be a tuple or list containing a variable name and optionally a default value")

    if len(matcher) == 1:
        var_name = matcher[0]
        default = None
    elif len(matcher) == 2:
        var_name, default = matcher
    else:
        raise ValueError("matcher must be a 1 or 2 element sequence (variable name, optional default)")

    if not isinstance(var_name, str):
        raise TypeError("environment variable name must be a string")

    value = os.getenv(var_name)

    if value is not None:
        return value
    if default is not None:
        return default

    raise RuntimeError(f"Environment variable '{var_name}' not set and no default value provided")

def _parse_image_ref(image_href: str) -> Tuple[str, str, bool]:
    """Parse an image href into composite parts.

    :param image_href: href of an image
    :returns: a tuple of the form (image_id, netloc, use_ssl)
    :raises ValueError:
    """
    if not isinstance(image_href, str):
        raise ValueError("image_href must be a string")
    image_href = image_href.strip()
    if not image_href:
        raise ValueError("image_href cannot be empty")

    # Helper to parse and validate
    def _do_parse(href: str) -> Tuple[str, str, bool]:
        try:
            parsed = urllib.parse.urlparse(href)
        except Exception as exc:
            raise ValueError(f"Failed to parse image_href: {href}") from exc

        scheme = parsed.scheme.lower()
        if scheme not in ("http", "https"):
            # If no scheme, insert http for parsing
            if not scheme:
                # prepend http to allow extraction of netloc and path
                parsed = urllib.parse.urlparse("http://" + href)
                scheme = parsed.scheme.lower()
            else:
                raise ValueError(f"Unsupported URL scheme: {scheme}")

        use_ssl = scheme == "https"

        netloc = parsed.netloc
        if not netloc:
            # If still no netloc, parsing failed
            raise ValueError(f"Unable to determine host from href: {href}")

        # Normalize image_id: remove leading slash, queries, fragments
        image_id = parsed.path.lstrip("/")
        comma = image_id.find("?")
        if comma != -1:
            image_id = image_id[:comma]
        hashidx = image_id.find("#")
        if hashidx != -1:
            image_id = image_id[:hashidx]
        return image_id, netloc, use_ssl

    # First attempt parsing normally
    try:
        return _do_parse(image_href)
    except ValueError:
        # Attempt to handle missing scheme scenarios
        if "://" not in image_href:
            return _do_parse("http://" + image_href)
        raise

def get_pattern(pattern, strip=True):
    """
    This method converts the given string to a regex pattern.
    It strips whitespace (if ``strip=True``), escapes all regex metacharacters,
    and returns a compiled ``re.Pattern`` instance.
    """
    if pattern is None:
        raise ValueError("pattern must not be None")
    if not isinstance(pattern, str):
        raise TypeError(f"pattern must be a string, got {type(pattern).__name__}")
    # Optional whitespace stripping
    if strip:
        pattern = pattern.strip()
    # Escape the pattern to treat it as a literal string
    escaped = re.escape(pattern)
    # Compile the escaped pattern
    try:
        return re.compile(escaped)
    except re.error as exc:
        raise ValueError(f"Failed to compile regex pattern: {exc}") from exc

