def make_array(shape, dtype=np.dtype("float32")):
    """
    Function to create an array with shape and dtype.

    Parameters
    ----------
    shape : tuple or int
        shape of the array to create
    dtype : `numpy.dtype` or None
        data-type of the array to create

    Returns
    -------
    numpy.ndarray
        Array of the specified shape and dtype.

    Raises
    ------
    TypeError
        If shape is not a tuple or int, or dtype is not convertible to numpy dtype.
    ValueError
        If shape contains non-positive integers.
    MemoryError
        If the allocation fails due to insufficient memory.
    """
    # Validate dtype
    try:
        if dtype is None:
            dtype = np.dtype("float32")
        elif not isinstance(dtype, np.dtype):
            dtype = np.dtype(dtype)
    except Exception as exc:
        raise TypeError(f"Invalid dtype: {dtype}") from exc

    # Validate and normalize shape
    if isinstance(shape, int):
        shape_tuple = (shape,)
    elif isinstance(shape, tuple) or isinstance(shape, list):
        shape_tuple = tuple(shape)
    else:
        raise TypeError(f"Shape must be an int, tuple, or list, got {type(shape).__name__}")

    if not shape_tuple:  # allow empty tuple for scalar
        pass
    else:
        for idx, dim in enumerate(shape_tuple):
            if not isinstance(dim, int):
                raise TypeError(f"Shape dimensions must be integers, got {type(dim).__name__} at index {idx}")
            if dim < 0:
                raise ValueError(f"Shape dimensions must be non-negative, got {dim} at index {idx}")

    # Attempt allocation
    try:
        return np.empty(shape_tuple, dtype=dtype)
    except MemoryError as mem_err:
        raise MemoryError(f"Could not allocate array of shape {shape_tuple} and dtype {dtype}") from mem_err
    except Exception as exc:
        # Catch any other exception from numpy/allocation
        raise RuntimeError(f"Array creation failed with error: {exc}") from exc

def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    """
    try:
        x_arr = np.asarray(x, dtype=float)
    except Exception as e:
        raise ValueError("Input must be a numeric scalar or array-like.") from e
    mu = 0.2
    sigma = 0.1
    result = np.exp(-((x_arr - mu)**2) / (2 * sigma**2))
    if np.isscalar(x):
        return float(result)
    return result

def protocol_handlers(cls, protocol_version=None):
    """
    Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    if protocol_version is not None and not isinstance(protocol_version, tuple):
        raise TypeError("protocol_version must be a tuple identifying a protocol version")

    # Retrieve the internal registry of handlers. If the class
    # hasn't defined one, treat it as empty.
    handlers = getattr(cls, "_protocol_handlers", {})
    if not isinstance(handlers, dict):
        # In case the attribute exists but is not a dict, ignore it
        handlers = {}

    if protocol_version is None:
        # Return a copy to prevent accidental external modifications
        return dict(handlers)

    handler = handlers.get(protocol_version)
    if handler is not None:
        return {protocol_version: handler}
    return {}

def from_raw_values(cls, values):
    """
    Create a Bookmarks object from a list of raw bookmark string values.

    You should not need to use this method unless you want to deserialize
    bookmarks.

    :param values: ASCII string values (raw bookmarks)
    :type values: Iterable[str]
    :return: A new instance of ``cls`` containing the supplied bookmarks.
    :rtype: cls
    """
    # Handle None or empty input
    if values is None:
        return cls()
    # Reject a single string (would be iterated over as individual characters)
    if isinstance(values, str):
        raise TypeError("values must be an iterable of strings, not a single string")
    # Ensure ``values`` is an iterable
    try:
        iterator = iter(values)
    except TypeError as exc:
        raise TypeError("values must be an iterable of string values") from exc

    processed = []
    for item in iterator:
        # Decode bytes to ASCII string
        if isinstance(item, bytes):
            try:
                item = item.decode('ascii')
            except UnicodeDecodeError as exc:
                raise ValueError(f"Bookmark byte value must be ASCII, got {item!r}") from exc
        elif not isinstance(item, str):
            raise TypeError(f"Bookmark values must be str or bytes, got {type(item).__name__}")
        processed.append(item)

    # Instantiate the Bookmarks object with the processed values.
    # If the constructor accepts an iterable directly, this should work.
    # If it expects a set, passing a list is still acceptable because it will be
    # iterated over. We attempt the simplest form first.
    try:
        instance = cls(processed)
    except Exception as exc:
        # In case the constructor expects a different signature, fall back to
        # passing a set of the values.
        try:
            instance = cls(set(processed))
        except Exception as exc2:
            raise TypeError("Failed to create Bookmarks instance with the provided values") from exc2
    return instance

