def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    # If no default was supplied, rely on dict's behaviour to raise KeyError
    if default is __marker:
        return super().pop(key)
    # If a default was supplied, use it to avoid raising KeyError
    return super().pop(key, default)

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    try:
        # Prefer the OrderedDict implementation which supports `last=True`
        return super().popitem(last=True)
    except TypeError:
        # Fallback to the base dict implementation
        return super().popitem()
    except KeyError:
        # Re‑raise with a clearer message
        raise KeyError("popitem(): dictionary is empty") from None

def popitem(self):
    """Remove and return a random `(key, value)` pair."""
    if not self:
        raise KeyError('dictionary is empty')
    try:
        import random
    except Exception as exc:
        raise RuntimeError("Failed to import random module") from exc
    keys = list(self.keys())
    key = random.choice(keys)
    value = self.pop(key)
    return key, value

