def identify_request(request: RequestType):
    """
    Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    def _get(arg, key):
        try:
            if isinstance(arg, dict):
                return arg.get(key)
            return getattr(arg, key, None)
        except Exception:
            return None

    try:
        # 1. Check for a public message
        public_msg = _get(request, "public_message")
        if public_msg:
            return True

        # 2. Check for a private message
        private_msg = _get(request, "private_message")
        if private_msg:
            return True

        # 3. Check for a legacy payload
        payload = _get(request, "payload")
        if payload:
            # if payload is a dict, look for typical legacy keys
            if isinstance(payload, dict):
                if "legacy_type" in payload or payload.get("type") == "legacy":
                    return True
                # Some legacy payloads might contain a nested dict with a 'legacy' flag
                if isinstance(payload.get("data"), dict) and payload["data"].get("legacy"):
                    return True
            # if payload is a string, a quick scan for 'legacy'
            if isinstance(payload, str) and "legacy" in payload.lower():
                return True

        # If none of the above succeeded, this is not a Diaspora request
        return False
    except Exception:
        # Any unexpected error should result in False rather than propagating
        return False

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    try:
        if not isinstance(tag, str):
            return False
        tag = tag.strip()
        if not tag:
            return False
        # Tags typically allow only alphanumerics, hyphens, and underscores.
        import re
        pattern = re.compile(r'^[A-Za-z0-9_-]+$')
        return bool(pattern.match(tag))
    except Exception:
        return False

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    # Ensure we have a valid node to work with
    if node is None:
        return {}
    try:
        # Retrieve children; this will work for most XML Element implementations
        children = list(node)
    except Exception:
        # If node is not iterable/acceptable, return empty dict
        return {}

    result = {}
    for child in children:
        try:
            key = child.tag
        except Exception:
            # Skip elements that do not have a tag attribute
            continue

        # Extract and clean the text content of the child
        try:
            text = child.text
            if text is not None:
                text = text.strip()
                if text == "":  # treat empty string as None
                    text = None
        except Exception:
            text = None

        # Handle duplicate tags by accumulating into a list
        if key in result:
            existing = result[key]
            if isinstance(existing, list):
                existing.append(text)
            else:
                result[key] = [existing, text]
        else:
            result[key] = text

    return result

def parse_diaspora_webfinger(document: str) -> dict:
    """
    Parse a Diaspora webfinger payload which may be in the newer JSON format or the older XRD (XML) format.
    Returns a dictionary with at least the keys 'subject' (a string) and 'links' (a list of dictionaries).
    Raises ValueError if the payload cannot be parsed or is missing required fields.
    """
    import json
    import xml.etree.ElementTree as ET

    if not document or not isinstance(document, str):
        raise ValueError("Document must be a non-empty string")

    # ----------- Try JSON first --------------------------------------------
    try:
        data = json.loads(document)
        if not isinstance(data, dict):
            raise ValueError("JSON webfinger must be an object")
        subject = data.get("subject")
        links = data.get("links")
        if subject is None:
            raise ValueError("JSON webfinger missing 'subject'")
        if links is None:
            links = []
        if not isinstance(links, list):
            raise ValueError("'links' must be a list")
        # Normalise each link dict
        normalised_links = []
        for link in links:
            if not isinstance(link, dict):
                continue
            normalised_links.append({
                "rel": link.get("rel"),
                "type": link.get("type"),
                "href": link.get("href")
            })
        return {"subject": subject, "links": normalised_links}
    except (json.JSONDecodeError, ValueError):
        # Not JSON – fall back to XML parsing
        pass

    # ----------- Try XML (XRD) --------------------------------------------
    try:
        root = ET.fromstring(document)
    except ET.ParseError as exc:
        raise ValueError(f"Unable to parse webfinger document: {exc}") from exc

    # XRD may use a default namespace; build a mapping for it
    ns = {}
    if root.tag.startswith("{"):
        uri, _, _ = root.tag[1:].partition("}")
        ns["atom"] = uri

    # Find subject
    subject_path = ".//{*}Subject"  # Ignore namespace
    subject = None
    for elem in root.iter():
        if elem.tag.endswith("Subject"):
            subject = elem.text
            break
    if subject is None:
        raise ValueError("XML webfinger missing 'Subject' element")

    # Find all Link elements; ignore other namespaces
    links = []
    for link in root.findall(".//{*}Link"):
        rel = link.attrib.get("rel")
        typ = link.attrib.get("type")
        href = link.attrib.get("href")
        if href:  # Only include if href present
            links.append({"rel": rel, "type": typ, "href": href})

    return {"subject": subject, "links": links}

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    if not isinstance(handle, str) or not handle:
        return None
    try:
        # Ensure handle is in 'acct:username@domain' format
        if not handle.startswith("acct:"):
            acct = f"acct:{handle}"
        else:
            acct = handle
        # Extract domain part
        if "@" not in acct:
            return None
        _, domain = acct.split("@", 1)
        # Build request URL
        import urllib.parse, urllib.request, json
        resource = urllib.parse.quote(acct, safe="")
        url = f"https://{domain}/.well-known/webfinger?resource={resource}"
        headers = {"Accept": "application/json"}
        req = urllib.request.Request(url, headers=headers, method="GET")
        with urllib.request.urlopen(req, timeout=10) as resp:
            if resp.status != 200:
                return None
            data = resp.read()
            try:
                text = data.decode("utf-8")
            except Exception:
                return None
            # Basic JSON validation
            try:
                json.loads(text)
            except json.JSONDecodeError:
                return None
            return text
    except Exception:
        return None

def retrieve_diaspora_host_meta(host):
    """
