        parsed = urllib.parse.urlparse(host)
        if not parsed.path or parsed.path.endswith('/'):
            url = parsed.scheme + '://' + parsed.netloc + '/.well-known/host-meta'
        else:
            # Use provided path if it already points to host-meta
            url = host if host.endswith('host-meta') else f"{host}/.well-known/host-meta"

    req = urllib.request.Request(url, headers={'Accept': 'application/xrd+xml'})
    try:
        with urllib.request.urlopen(req, timeout=10) as response:
            content = response.read()
    except urllib.error.HTTPError as e:
        raise RuntimeError(f"HTTP error {e.code} when retrieving host-meta from {url}") from e
    except urllib.error.URLError as e:
        raise RuntimeError(f"URL error when retrieving host-meta from {url}: {e.reason}") from e
    except Exception as e:
        raise RuntimeError(f"Unexpected error when retrieving host-meta from {url}") from e

    try:
        root = ET.fromstring(content)
    except ET.ParseError as e:
        raise RuntimeError(f"Error parsing XRD XML from {url}: {e}") from e

    return root

def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    """Helper method to send a document via POST.

    Additional ``*args`` and ``**kwargs`` will be passed on to ``requests.post``.

    :arg url: Full url to send to, including protocol
    :arg data: Dictionary (will be form-encoded), bytes, or file-like object to send in the body
    :arg timeout: Seconds to wait for response (defaults to 10)
    :arg method: Method to use, defaults to post
    :returns: Tuple of status code (int or None) and error (exception class instance or None)
    """
    try:
        import requests
    except ImportError as e:
        return None, e

    if not isinstance(url, str) or not url:
        return None, ValueError("url must be a non-empty string")

    meth = method.lower() if isinstance(method, str) else method
    # Ensure the method is a callable attribute on requests
    try:
        request_func = getattr(requests, meth)
    except AttributeError:
        return None, ValueError(f"Unsupported HTTP method: {method}")

    # Prepare arguments
    request_kwargs = {
        'url': url,
        'timeout': timeout,
        'data': data,
    }
    # Merge any additional keyword arguments
    request_kwargs.update(kwargs)

    try:
        response = request_func(*args, **request_kwargs)
        return response.status_code, None
    except Exception as exc:
        return None, exc

def list_of_file_names(settings_dirs, spec_option):
    """
    Return a list of file names (full paths) found in the provided directories that
    match the given specification option.

    Parameters
    ----------
    settings_dirs : Iterable[str] or str
        One or more directory paths to search for files.
    spec_option : str or None
        Specification for matching files. If ``None`` or ``'*'`` all files are returned.
        If the string starts and ends with '/', it is treated as a regular expression
        pattern. Otherwise it is interpreted as a filename suffix (e.g. '.conf').

    Returns
    -------
    List[str]
        Sorted list of matching file paths. Any inaccessible directories are skipped.

    Notes
    -----
    - If `settings_dirs` is a string, it is interpreted as a single directory.
    - The function does not lift files from subdirectories; only the top level contents
      of each listed directory are considered.
    - Errors such as non-existent directories or permission issues are ignored; the
      corresponding path is simply omitted from the result.
    """
    import os
    import re
    from collections import OrderedDict

    # Normalise settings_dirs to an iterable of directory strings
    if isinstance(settings_dirs, (str, bytes)):
        directories = [settings_dirs]
    else:
        try:
            directories = list(settings_dirs)
        except Exception:
            raise TypeError("settings_dirs must be an iterable of directory paths")
    if not directories:
        return []

    # Prepare matching criteria
    all_files = spec_option is None or spec_option == '*'
    regex_pattern = None
    suffix = None
    if not all_files:
        if isinstance(spec_option, str):
            if spec_option.startswith('/') and spec_option.endswith('/'):
                # treat as regex; strip the slashes
                try:
                    regex_pattern = re.compile(spec_option[1:-1])
                except re.error:
                    # fall back to suffix matching
                    suffix = spec_option
            else:
                suffix = spec_option
        else:
            raise TypeError("spec_option must be a string pattern or None")

    result_set = set()
    for dir_path in directories:
        if not isinstance(dir_path, (str, bytes)):
            continue
        try:
            for entry in os.listdir(dir_path):
                full_path = os.path.join(dir_path, entry)
                if not os.path.isfile(full_path):
                    continue
                if all_files:
                    result_set.add(full_path)
                    continue
                # suffix match
                if suffix is not None:
                    if entry.endswith(suffix):
                        result_set.add(full_path)
                    continue
                # regex match
                if regex_pattern is not None:
                    if regex_pattern.search(entry):
                        result_set.add(full_path)
        except (FileNotFoundError, NotADirectoryError, PermissionError):
            # ignore directories that cannot be accessed
            continue

    # Return sorted list for stable output
    return sorted(result_set)

