def plugins_manager(cls):
    """Gets the plugin manager. """
    # Lazily create or retrieve a singleton plugin manager instance.
    if not hasattr(cls, "_plugin_manager") or cls._plugin_manager is None:
        try:
            # Define a minimal plugin manager with simple registration logic.
            class _PluginManager:
                def __init__(self):
                    self._plugins = {}

                def register(self, name, plugin):
                    if name in self._plugins:
                        raise KeyError(f"Plugin with name '{name}' is already registered.")
                    self._plugins[name] = plugin

                def get(self, name):
                    return self._plugins.get(name)

                def all_plugins(self):
                    return list(self._plugins.items())

            cls._plugin_manager = _PluginManager()
        except Exception as exc:
            raise RuntimeError(f"Failed to initialize plugin manager: {exc}") from exc
    return cls._plugin_manager

def validate_from_content(cls, spec_content=None):
    """
    validates that spec (YAML) content has all required fields

    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    # Basic sanity check for input
    if spec_content is None:
        raise IRValidatorException("Spec content is None")

    # If the spec content is provided as a dictionary, use it directly.
    if isinstance(spec_content, dict):
        data = spec_content
    elif isinstance(spec_content, str):
        # Attempt to parse YAML content
        try:
            import yaml
            data = yaml.safe_load(spec_content)
        except Exception as exc:
            raise IRValidatorException(f"Failed to parse YAML spec content: {exc}")

    else:
        raise IRValidatorException("Spec content must be either a YAML string or a dict")

    # Validate that the result is a mapping
    if not isinstance(data, dict):
        raise IRValidatorException("Parsed spec content must be a mapping (dictionary)")

    # Define the set of mandatory keys that must exist in the spec
    required_keys = {"name", "description", "spec"}
    missing_keys = [key for key in required_keys if key not in data]
    if missing_keys:
        raise IRValidatorException(
            f"Missing required fields in spec: {', '.join(missing_keys)}"
        )

    return data

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    try:
        spec = getattr(self, "spec", {})
    except Exception as exc:  # pragma: no cover
        # If accessing spec itself fails, return empty dict
        return {}
    if not isinstance(spec, dict):
        # Spec must be a dictionary; otherwise, cannot resolve defaults
        raise TypeError(f"spec should be a dict, got {type(spec).__name__}")

    # Import os inside the method so that the module does not require a top‑level import
    try:
        import os
    except Exception:  # pragma: no cover
        os = None

    for name, definition in spec.items():
        # If the definition is not a mapping, treat it as the default value directly
        if not isinstance(definition, dict):
            defaults[name] = definition
            continue

        # Resolve value based on priority: env variable > default_factory > default
        value = None
        if "env" in definition and os and definition["env"]:
            env_val = os.getenv(definition["env"])
            if env_val is not None:
                value = env_val

        if value is None and "default_factory" in definition:
            factory = definition["default_factory"]
            if callable(factory):
                try:
                    value = factory()
                except Exception as exc:  # pragma: no cover
                    raise RuntimeError(
                        f"Error calling default_factory for argument '{name}': {exc}"
                    ) from exc
            else:
                raise TypeError(
                    f"default_factory for argument '{name}' must be callable, got {type(factory).__name__}"
                )

        if value is None and "default" in definition:
            value = definition["default"]

        # If still no value, default to None (explicitly set or implied)
        defaults[name] = value

    return defaults

