def validate_requires_args(self, args):
        """Check if all the required arguments have been provided."""
        # Ensure the input is a dictionary-like object
        if not isinstance(args, dict):
            raise TypeError("args must be a dictionary of keyword arguments")

        # Retrieve the list/tuple of required argument names
        required = getattr(self, "requires_args", [])
        if required is None:
            required = []

        # Normalise to an iterable sequence
        if not hasattr(required, "__iter__") or isinstance(required, (str, bytes)):
            raise TypeError("requires_args must be an iterable of argument names")

        # Verify each required argument is present and not None
        for name in required:
            if name not in args or args[name] is None:
                raise ValueError(f"Missing required argument: {name}")

        return True

def validate_length_args(self, args):
        """Check if value of arguments is not longer than length specified.

        :param args: The received arguments, expected to be a dictionary
            mapping argument names to their values.
        """
        # Ensure args is a mapping
        if not isinstance(args, dict):
            raise TypeError("args must be a dictionary mapping argument names to values")

        # If no length constraints defined, nothing to validate
        max_lengths = getattr(self, "max_lengths", None)
        if not isinstance(max_lengths, dict):
            return

        errors = []
        for key, value in args.items():
            if key not in max_lengths:
                continue
            max_len = max_lengths[key]
            # Attempt to get length of value
            try:
                val_len = len(value)
            except Exception:
                errors.append(
                    f"Cannot determine length of argument '{key}': unsupported type '{type(value).__name__}'"
                )
                continue
            if val_len > max_len:
                errors.append(
                    f"Argument '{key}' length {val_len} exceeds maximum {max_len}"
                )

        if errors:
            raise ValueError("; ".join(errors))

def validate_choices_args(self, args):
    """
    Check if value of choice arguments is one of the available choices.

    :param args: A mapping of argument names to the supplied values.
    """
    if not hasattr(self, "choices"):
        raise AttributeError("The object does not have a 'choices' attribute.")

    if not isinstance(args, dict):
        raise TypeError("`args` must be a dictionary of argument names to values.")

    for arg_name, value in args.items():
        # Only validate arguments that have a defined list of choices
        if arg_name not in self.choices:
            continue

        allowed = self.choices[arg_name]
        if allowed is None:
            # No explicit choices specified; nothing to validate
            continue

        # If the supplied value is iterable (but not a string), treat each element as a choice
        if isinstance(value, (list, tuple, set)):
            for element in value:
                if element not in allowed:
                    raise ValueError(
                        f"Invalid value for argument '{arg_name}': {element}. "
                        f"Allowed values are: {allowed}."
                    )
        else:
            if value not in allowed:
                raise ValueError(
                    f"Invalid value for argument '{arg_name}': {value}. "
                    f"Allowed values are: {allowed}."
                )

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                    spec_option):
        """Build the complex argument type

        :param subcommand: the command name
        :param type_name: the complex type name
        :param option_name: the option name
        :param spec_option: option's specifications
        :return: the complex type instance
        """
        # Basic input validation
        if not isinstance(subcommand, str) or not subcommand:
            raise ValueError("subcommand must be a non-empty string")
        if not isinstance(type_name, str) or not type_name:
            raise ValueError("type_name must be a non-empty string")
        if not isinstance(option_name, str) or not option_name:
            raise ValueError("option_name must be a non-empty string")
        if not isinstance(spec_option, dict):
            raise TypeError("spec_option must be a dictionary")

        import re

        # Retrieve optional specification fields
        # allow both 'type' and 'convert' keys for user convenience
        conv = spec_option.get('type', spec_option.get('convert'))
        pattern = spec_option.get('pattern')
        choices = spec_option.get('choices')
        default = spec_option.get('default')

        def _validate(value):
            """Inner validation function for the complex type."""
            try:
                # Apply type conversion if requested
                if conv:
                    if conv == 'int':
                        value = int(value)
                    elif conv == 'float':
                        value = float(value)
                    elif conv == 'bool':
                        # Basic string to bool conversion
                        if isinstance(value, bool):
                            pass
                        elif isinstance(value, str):
                            low = value.lower()
                            if low in ('true', '1', 'yes', 'y'):
                                value = True
                            elif low in ('false', '0', 'no', 'n'):
                                value = False
                            else:
                                raise ValueError(f"Invalid boolean value: {value!r}")
                        else:
                            raise ValueError(f"Cannot convert {value!r} to bool")
                    else:
                        # Treat unknown conv as a callable
                        value = conv(value)

                # Validate against a set of allowed choices
                if choices is not None and value not in choices:
                    raise ValueError(f"Value {value!r} not in allowed choices {choices}")

                # Regex pattern matching
                if pattern is not None:
                    if not re.fullmatch(pattern, str(value)):
                        raise ValueError(f"Value {value!r} does not match pattern {pattern!r}")

                return value
            except Exception as exc:
                raise ValueError(
                    f"Failed to validate value {value!r} for option {option_name!r}: {exc}"
                ) from exc

        # Construct a minimal-complex-type representation
        complex_type = {
            'subcommand': subcommand,
            'name': type_name,
            'option': option_name,
            'spec': spec_option,
            'validate': _validate,
            'default': default
        }
        return complex_type

