def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """
    Wraps the 'ansible-playbook' CLI.

    :param ir_workspace: An Infrared Workspace object representing the active workspace.
    :param ir_plugin: An InfraredPlugin object of the current plugin.
    :param playbook_path: The path to the playbook to invoke.
    :param verbose: Ansible verbosity level (integer 0-5). If None, no verbosity flag is added.
    :param extra_vars: dict of variables to pass to Ansible as --extra-vars.
    :param ansible_args: dict of additional ansible-playbook arguments to pass directly to the CLI.
    :returns: subprocess.CompletedProcess instance containing the execution results.
    :raises FileNotFoundError: If the specified playbook does not exist.
    :raises RuntimeError: If an invalid verbosity level is provided or the command fails.
    """
    import subprocess
    import json
    import os
    from pathlib import Path

    # Validate the playbook path
    playbook = Path(playbook_path)
    if not playbook.is_file():
        raise FileNotFoundError(f"Playbook not found: {playbook_path}")

    # Base command
    cmd = ["ansible-playbook", str(playbook)]

    # Handle ansible_args: dict where key is flag, value is optional argument
    if ansible_args:
        if not isinstance(ansible_args, dict):
            raise TypeError("ansible_args must be a dictionary")
        for key, value in ansible_args.items():
            if not isinstance(key, str):
                raise TypeError("ansible_args keys must be strings")
            # Ensure flag starts with '--' or '-'
            if not key.startswith("-"):
                key = f"--{key}"
            cmd.append(key)
            if value is not None:
                # Support list/tuple values by converting to a space-separated string
                if isinstance(value, (list, tuple)):
                    value = " ".join(map(str, value))
                cmd.append(str(value))

    # Add verbosity
    if verbose is not None:
        try:
            level = int(verbose)
        except Exception:
            raise RuntimeError(f"Invalid verbosity level: {verbose}")
        if level < 0 or level > 5:
            raise RuntimeError("Verbosity level must be between 0 and 5")
        if level > 0:
            cmd.append("-" + "v" * level)

    # Add extra_vars as JSON string
    if extra_vars is not None:
        if not isinstance(extra_vars, dict):
            raise TypeError("extra_vars must be a dictionary")
        try:
            json_str = json.dumps(extra_vars)
        except Exception as e:
            raise RuntimeError(f"Failed to serialize extra_vars: {e}")
        cmd.extend(["--extra-vars", json_str])

    # Execute the command
    try:
        result = subprocess.run(
            cmd,
            cwd=str(ir_workspace.path if hasattr(ir_workspace, "path") else os.getcwd()),
            capture_output=True,
            text=True,
            check=False,
        )
    except FileNotFoundError:
        raise RuntimeError("ansible-playbook command not found. Ensure Ansible is installed and in PATH.")
    except Exception as e:
        raise RuntimeError(f"An error occurred while executing ansible-playbook: {e}")

    # Log output if verbose
    if verbose:
        print(result.stdout)
        if result.stderr:
            print(result.stderr, file=sys.stderr)

    if result.returncode != 0:
        raise RuntimeError(
            f"ansible-playbook failed with exit code {result.returncode}.\n"
            f"stdout: {result.stdout}\n"
            f"stderr: {result.stderr}"
        )

    return result

def _convert_non_cli_args(self, parser_name, values_dict):
    """
    Casts argument values to the types expected by the parser, modifying values_dict in-place.

    The class should provide a mapping `self.arg_type_map` with the following structure:
        {
            "parser_name": {
                "arg_name": expected_type,   # e.g. int, float, bool, list, str
                ...
            },
            ...
        }
    If an argument is not present in the mapping, it will be left unchanged.

    Parameters
    ----------
    parser_name : str
        The name of the parser (e.g., 'main', 'virsh', 'ospd').
    values_dict : dict
        Dictionary mapping argument names to string values. The values are mutated in-place.

    Returns
    -------
    None
    """
    # Retrieve the expected type mapping for the parser, if available
    type_map = getattr(self, 'arg_type_map', {}).get(parser_name, {})
    if not type_map:
        # No type information; nothing to convert
        return

    for arg, expected_type in type_map.items():
        if arg not in values_dict:
            continue

        value = values_dict[arg]
        # Skip if already not a string or is None
        if not isinstance(value, str) or value is None:
            continue

        try:
            if expected_type is str:
                # No conversion needed, but ensure it's a plain string
                values_dict[arg] = str(value)
            elif expected_type is int:
                values_dict[arg] = int(value)
            elif expected_type is float:
                values_dict[arg] = float(value)
            elif expected_type is bool:
                lower = value.lower()
                if lower in ('true', '1', 'yes', 'y'):
                    values_dict[arg] = True
                elif lower in ('false', '0', 'no', 'n'):
                    values_dict[arg] = False
                else:
                    # Unable to parse boolean, keep original string
                    pass
            elif expected_type is list:
                # Assume comma-separated values; strip whitespace
                if value.strip() == '':
                    values_dict[arg] = []
                else:
                    parts = [p.strip() for p in value.split(',')]
                    values_dict[arg] = parts
            elif expected_type is set:
                if value.strip() == '':
                    values_dict[arg] = set()
                else:
                    values_dict[arg] = {p.strip() for p in value.split(',')}
            else:
                # Attempt generic conversion using the type constructor
                values_dict[arg] = expected_type(value)
        except Exception:
            # On any conversion error, leave the original string value
            pass

def get_plugin_spec_flatten_dict(plugin_dir):
    """
    Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    # Helper functions
    def _flatten(prefix, obj, out):
        if isinstance(obj, dict):
            for k, v in obj.items():
                key = f"{prefix}.{k}" if prefix else k
                _flatten(key, v, out)
        elif isinstance(obj, list):
            for idx, item in enumerate(obj):
                key = f"{prefix}[{idx}]" if prefix else f"[{idx}]"
                _flatten(key, item, out)
        else:
            out[prefix] = obj

    # Validate plugin_dir
    if not isinstance(plugin_dir, (str, bytes, os.PathLike)):
        raise TypeError(f"plugin_dir must be a string or PathLike object, got {type(plugin_dir)}")
    plugin_dir = os.fspath(plugin_dir)

    if not os.path.isdir(plugin_dir):
        raise ValueError(f"plugin_dir '{plugin_dir}' is not a directory or does not exist")

    # Find spec file (yaml or json)
    spec_path = None
    for fname in ("plugin.yaml", "plugin.yml", "plugin.json"):
        potential = os.path.join(plugin_dir, fname)
        if os.path.isfile(potential):
            spec_path = potential
            break

    if spec_path is None:
        raise FileNotFoundError(f"No plugin spec file found in '{plugin_dir}' (expected plugin.yaml, plugin.yml, or plugin.json)")

    # Load spec
    spec_data = None
    try:
        if spec_path.lower().endswith(".json"):
            with open(spec_path, "r", encoding="utf-8") as f:
                spec_data = json.load(f)
        else:
            import yaml  # local import to avoid unnecessary dependency
            with open(spec_path, "r", encoding="utf-8") as f:
                spec_data = yaml.safe_load(f)
    except Exception as e:
        raise ValueError(f"Failed to load spec file '{spec_path}': {e}") from e

    if not isinstance(spec_data, (dict, list)):
        raise ValueError(f"Spec file '{spec_path}' does not contain a mapping or list at the top level")

    # Flatten spec
    flat_dict = {}
    try:
        # If top level is a list, use a placeholder key
        if isinstance(spec_data, list):
            _flatten("[0]", spec_data[0] if spec_data else {}, flat_dict)
            for idx in range(1, len(spec_data)):
                _flatten(f"[{idx}]", spec_data[idx], flat_dict)
        else:
            _flatten("", spec_data, flat_dict)
    except Exception as e:
        raise ValueError(f"Error while flattening spec: {e}") from e

    return flat_dict

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    import os
    env_var = "CONFIG_PATH"
    try:
        current = os.environ.get(env_var)
        if not current:
            # Default to a "config.yaml" in the same directory as this file
            default_path = os.path.abspath(
                os.path.join(os.path.dirname(__file__), "config.yaml")
            )
            os.environ[env_var] = default_path
    except Exception:
        # Fail silently; caller can handle missing config path if needed
        pass
